        copy(w, 912, 1056, 144)
        return 0
    if phase == 8:
        if regular(w, 912, 256, 192) == 0:
            return 10
        if stable(w, 768, 912) == 0:
            return 12
        return 0
    if phase == 9:
        if regular(w, 912, 256, 192) == 0:
