    if length(s) < 16 or uint(s, 0, 8) != 1:
        return bad(w, 16)
    n = uint(s, 8, 8)
    if n > 16 or length(s) != 16 + n:
        return bad(w, 16)
    op = 0
    if n == 5 and uint(s, 16, 5) == BUILD_WORD:
        op = 1
    if n == 4 and uint(s, 16, 4) == PACK_WORD:
        op = 2
    if op == 0:
        return bad(w, 16)
    put(w, 8, op)
    put(w, 16, 1)
    return 0

def admit(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) < 24 or length(s) > 67108864:
        return bad(w, 16)
    if uint(s, 0, 8) != BUNDLE_MAGIC or uint(s, 16, 8) != 0:
        return bad(w, 16)
    count = uint(s, 8, 8)
    op = get(w, 8)
    if count == 0 or count > 128:
        return bad(w, 16)
    if op == 2 and count != 3 and count != 6:
        return bad(w, 16)
    at = 24
    i = 0
    bits = 0
    while i < count:
        if at > length(s) or length(s) - at < 24:
            return bad(w, 16)
        n = uint(s, at, 8)
        mode = uint(s, at + 8, 8)
        size = uint(s, at + 16, 8)
        if n == 0 or n > 127 or mode != 256 or size == 0 or size > 1048576:
            return bad(w, 16)
        at = at + 24
        if n > length(s) - at:
            return bad(w, 16)
        j = 0
        while j < n:
            v = byte(s, at + j)
            if alnum(v) == 0:
                if j == 0 or v != 46 and v != 45 and v != 95:
                    return bad(w, 16)
            j = j + 1
        if op == 1:
            if n < 7 or n > 123:
                return bad(w, 16)
            suffix = 0
            if uint(s, at + n - 6, 6) == SUFFIX_WORD:
                suffix = 1
            if n >= 8 and uint(s, at + n - 7, 7) == ASM_SUFFIX_WORD:
                suffix = 1
            if suffix == 0:
                return bad(w, 16)
        j = 0
        while j < i:
            row = 4096 + j * 40
            if get(w, row + 8) == n:
                k = 0
                same = 1
                while k < n:
                    if byte(s, at + k) != byte(s, get(w, row) + k):
                        same = 0
                    k = k + 1
                if same == 1:
                    return bad(w, 16)
            j = j + 1
        row = 4096 + i * 40
        put(w, row, at)
        put(w, row + 8, n)
        if op == 2:
            which = role(s, at, n)
            if which == 0:
                return bad(w, 16)
            which = which - 1
            bits = bits | (1 << which)
            put(w, 256 + which * 16, at + n)
            put(w, 264 + which * 16, size)
        at = at + n
        if size > length(s) - at:
            return bad(w, 16)
        put(w, row + 16, at)
        put(w, row + 24, size)
        at = at + size
        i = i + 1
    if at != length(s):
        return bad(w, 16)
    if op == 2:
        if count == 3 and bits != 56 or count == 6 and bits != 63:
            return bad(w, 16)
        put(w, 16, 5)
    else:
        if length(o) < 24:
            return bad(w, 17)
        write(o, 0, BUNDLE_MAGIC, 8)
        write(o, 8, count * 2, 8)
        write(o, 16, 0, 8)
        put(w, 16, 2)
    put(w, 24, count)
    put(w, 32, 0)
    put(w, 40, length(s))
    put(w, 48, 24)
    return 0

def select(s:readbuf, w:mutbuf) -> u32:
    op = get(w, 8)
    index = get(w, 32)
    if op == 1:
        if get(w, 16) != 2 or index > get(w, 24):
            return bad(w, 16)
        if index == get(w, 24):
            put(w, 88, get(w, 48))
            put(w, 16, 7)
            return 3
        row = 4096 + index * 40
        put(w, 56, get(w, row + 16))
        put(w, 64, get(w, row + 24))
    else:
        if get(w, 16) != 5 or index > 3:
            return bad(w, 16)
        if get(w, 24) == 3 or index == 3:
            put(w, 16, 6)
            return 2
        put(w, 56, get(w, 256 + index * 16))
        put(w, 64, get(w, 264 + index * 16))
    if get(w, 56) > length(s) or get(w, 64) > length(s) - get(w, 56):
        return bad(w, 16)
    put(w, 16, 3)
    return 1

def consume(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if get(w, 16) != 3:
        return bad(w, 16)
    size = get(w, 72)
    if size == 0 or size > 1048576:
        return bad(w, 18)
    index = get(w, 32)
    if get(w, 8) == 2:
        if index >= 3 or get(w, 264 + (index + 3) * 16) != size:
            return bad(w, 19)
        source = get(w, 256 + (index + 3) * 16)
        if source > length(s) or size > length(s) - source:
            return bad(w, 16)
        i = 0
        while i < size:
            if byte(s, source + i) != byte(w, 65536 + i):
                return bad(w, 19)
            i = i + 1
        put(w, 16, 5)
    else:
        if index >= get(w, 24) or index >= 128:
            return bad(w, 16)
        row = 4096 + index * 40
        n = get(w, row + 8)
        source = get(w, row + 16)
        source_size = get(w, row + 24)
        at = get(w, 48)
        need = 52 + n * 2 + source_size + size
        if at > length(o) or need > length(o) - at or at > 67108864 or need > 67108864 - at:
            return bad(w, 17)
        write(o, at, n, 8)
        write(o, at + 8, 256, 8)
        write(o, at + 16, source_size, 8)
        copy_bytes(s, o, get(w, row), at + 24, n)
        at = at + 24 + n
        copy_bytes(s, o, source, at, source_size)
        at = at + source_size
        write(o, at, n + 4, 8)
        write(o, at + 8, 256, 8)
        write(o, at + 16, size, 8)
        copy_bytes(s, o, get(w, row), at + 24, n)
        write(o, at + 24 + n, IMAGE_SUFFIX_WORD, 4)
        at = at + 28 + n
        i = 0
        while i < size:
            store(o, at + i, byte(w, 65536 + i))
            i = i + 1
        put(w, 48, at + size)
        put(w, 16, 2)
    put(w, 32, index + 1)
    return 0

def frame(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if get(w, 16) != 6:
        return bad(w, 16)
    size = 32 + get(w, 312) + get(w, 328) + get(w, 344)
    if size > length(o):
        return bad(w, 17)
    write(o, 0, PACK_MAGIC, 8)
    at = 32
    i = 0
    while i < 3:
        source = get(w, 304 + i * 16)
        n = get(w, 312 + i * 16)
        if n == 0 or n > 1048576 or source > length(s) or n > length(s) - source:
            return bad(w, 16)
        write(o, 8 + i * 8, n, 8)
        copy_bytes(s, o, source, at, n)
        at = at + n
        i = i + 1
    put(w, 80, at)
    put(w, 16, 8)
    return 0

def bad(w:mutbuf, code:u32) -> u32:
    put(w, 16, 255)
    return code

ROLE_FUNCTION

def alnum(v:u64) -> u64:
    if v >= 48 and v <= 57 or v >= 65 and v <= 90 or v >= 97 and v <= 122:
        return 1
    return 0

def copy_bytes(s:readbuf, o:mutbuf, source:u64, target:u64, n:u64) -> u64:
    i = 0
    while i < n:
        store(o, target + i, byte(s, source + i))
        i = i + 1
    return 0

def uint(s:readbuf, at:u64, n:u64) -> u64:
    v = 0
    i = 0
    while i < n:
        v = v | byte(s, at + i) << (i * 8)
        i = i + 1
    return v

def get(w:mutbuf, at:u64) -> u64:
    v = 0
    i = 0
    while i < 8:
        v = v | byte(w, at + i) << (i * 8)
        i = i + 1
    return v

def put(w:mutbuf, at:u64, v:u64) -> u64:
    return write(w, at, v, 8)

def write(o:mutbuf, at:u64, v:u64, n:u64) -> u64:
    i = 0
    while i < n:
        store(o, at + i, v >> (i * 8) & 255)
        i = i + 1
    return 0
